'use strict';
(()=>{
const builtIn={builtin:true,manifest:{name:'Knaben · music source search'}};let losslessOnly=true;let addon=builtIn,revision=0,controller=null,searchTerm='';
function https(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
function message(text){const node=$('#addon-status');if(node)node.textContent=text}
async function json(url){const response=await fetch(url,{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('The addon request failed. Check its URL or configuration.');return response.json()}
function page(term=''){revision++;controller?.abort();controller=new AbortController();searchTerm=term;modal(`<div class="eyebrow">DISCOVERY → SOURCE → PLAYBACK</div><h2>Find cloud music.</h2><p>Search external lossless releases and play audio through your connected AllDebrid account. No file-host link or addon URL required.</p>${addon?`<p class="note">Search provider: <b>${escapeHTML(addon.manifest.name)}</b> <button id="addon-remove">${addon.builtin?"Use a custom addon":"Change source"}</button></p><form id="addon-search-form"><label for="addon-search">Artist, album, or track</label><input id="addon-search" type="text" maxlength="150" placeholder="Search music"><button class="primary" id="addon-search-button">Find sources ↗</button></form>`:`<form id="addon-connect-form"><label for="addon-url">Music addon manifest URL</label><input id="addon-url" type="url" required placeholder="https://your-music-addon.example/manifest.json" autocomplete="off"><button class="primary" id="addon-connect-button">Connect music addon ↗</button></form><p class="note">Use a Stremio-compatible music addon that provides a searchable catalog and streams. Oktawka has no built-in source indexer. Your AllDebrid key alone cannot discover music.</p>`}<p id="addon-status" role="status" aria-live="polite" class="note"></p><div id="addon-results"></div><p class="note">Addon configuration stays in memory for this tab. Oktawka never sends your AllDebrid key to an addon. Supports HTTPS sources and torrent audio through AllDebrid. Uncached torrents may need preparation in your AllDebrid account. Video sources and archives cannot play as music.</p>`);if(addon){$('#addon-search').value=term;$('#addon-remove').onclick=()=>{addon=addon.builtin?null:builtIn;page(term)};$('#addon-search-form').onsubmit=e=>{e.preventDefault();search($('#addon-search').value.trim())};if(term&&addon.builtin)search(term)}else $('#addon-connect-form').onsubmit=async e=>{e.preventDefault();const version=revision,url=https($('#addon-url').value.trim());if(!url||!new URL(url).pathname.endsWith('/manifest.json'))return message('Enter an HTTPS addon URL ending in /manifest.json.');$('#addon-connect-button').disabled=true;message('Checking the music addon…');try{const manifest=await json(url);if(version!==revision)return;const catalogs=(manifest.catalogs||[]).filter(c=>typeof c.id==='string'&&typeof c.type==='string'&&Array.isArray(c.extra)&&c.extra.some(x=>x.name==='search'));const streams=(manifest.resources||[]).some(r=>r==='stream'||r?.name==='stream');if(!manifest.id||!manifest.name||!catalogs.length||!streams)throw new Error('This addon needs a searchable catalog and a stream resource. Use a music source addon.');addon={base:url.slice(0,-'manifest.json'.length),manifest,catalogs};page(term)}catch(e){if(version===revision)message(e.name==='AbortError'?'Request cancelled.':'Could not connect: '+(e instanceof TypeError?'the addon may be offline or not allow browser access.':e.message))}finally{if(version===revision)$('#addon-connect-button').disabled=false}}}
function route(resource,type,id,extra){return addon.base+resource+'/'+encodeURIComponent(type)+'/'+encodeURIComponent(id)+(extra?'/search='+encodeURIComponent(extra):'')+'.json'}
async function search(term){if(!term)return message('Enter an artist, album, or track.');const version=++revision;controller?.abort();controller=new AbortController();$('#addon-search-button').disabled=true;message(addon.builtin?'Searching external lossless releases…':'Searching the addon’s catalogs…');$('#addon-results').innerHTML='';try{if(addon.builtin){await searchBuiltIn(term,version);return;}const catalogs=addon.catalogs.slice(0,3);const results=await Promise.allSettled(catalogs.map(c=>json(route('catalog',c.type,c.id,term))));if(version!==revision)return;const entries=[],seen=new Set();results.forEach((r,i)=>{if(r.status==='fulfilled'&&Array.isArray(r.value.metas))for(const m of r.value.metas){if(typeof m.id!=='string'||typeof m.name!=='string')continue;const type=m.type||catalogs[i].type,key=type+':'+m.id;if(!seen.has(key)){entries.push({...m,type});seen.add(key)}}});const list=entries.slice(0,60);$('#addon-results').innerHTML=list.map((m,i)=>`<button class="cloud-file" data-addon-item="${i}"><span>♫</span><span><b>${escapeHTML(m.name)}</b><small>${escapeHTML(addon.manifest.name)} · find streams</small></span><span>↗</span></button>`).join('');message(list.length?`${list.length} results. Choose an item to see sources.`:results.every(r=>r.status==='rejected')?'The addon could not be reached. Try again later.':'No matching music found in this addon.');$('#addon-results').querySelectorAll('[data-addon-item]').forEach(b=>b.onclick=()=>streams(list[Number(b.dataset.addonItem)]))}catch(e){if(version===revision){message(e.name==='AbortError'?'Music search timed out or was cancelled. Try again.':e instanceof TypeError?'Could not reach the music search service. Check your connection and retry.':e.message||'Music search failed. Retry shortly.');const retry=document.createElement('button');retry.className='primary';retry.textContent='Retry search ↻';retry.onclick=()=>search(term);$('#addon-results').append(retry)}}finally{if(version===revision)$('#addon-search-button').disabled=false}}
async function streams(item){const version=revision;if(item.hash){await torrentAudio(item.hash,item,version);return;}message('Finding sources for '+item.name+'…');$('#addon-results').innerHTML='';try{const data=await json(route('stream',item.type,item.id));if(version!==revision)return;const sources=Array.isArray(data.streams)?data.streams:[];const supported=sources.filter(s=>https(s.url)||/^[a-f0-9]{40}$/i.test(s.infoHash||'')).slice(0,50);$('#addon-results').innerHTML=`<h3>${escapeHTML(item.name)}</h3><button class="source-back" id="addon-back">← Search results</button>`+supported.map((s,i)=>`<div class="debrid-result"><b>${escapeHTML(s.name||'Audio source')}</b><p class="note">${escapeHTML(s.description||s.title||'Quality unverified')}</p><button class="primary" data-addon-resolve="${i}">Resolve with AllDebrid ↗</button>${https(s.url)?`<button class="source-back" data-addon-direct="${i}">Use direct audio</button>`:''}</div>`).join('');$('#addon-back').onclick=()=>search($('#addon-search').value.trim());message(supported.length?`${supported.length} sources. Choose audio through AllDebrid; quality depends on the original file.`:sources.some(s=>s.infoHash)?'This addon returned an unsupported torrent hash format.':'No supported HTTPS audio sources returned. Try another music addon.');$('#addon-results').querySelectorAll('[data-addon-resolve]').forEach(b=>b.onclick=async()=>{b.disabled=true;message('Resolving the selected source…');try{const selected=supported[Number(b.dataset.addonResolve)];if(!https(selected.url)&&selected.infoHash){await torrentAudio(selected.infoHash,item,version);return;}const result=await window.monoResolveAllDebrid(selected.url);if(version!==revision)return;if(result.delayed)throw new Error('This source needs more preparation. Try another source.');addAudio(result.link,result.filename||item.name,item.name);message('Added to your music library. Select the track to play.');b.textContent='✓ Added'}catch(e){if(version===revision){if(reconnectForPlayback(e,v=>streams(item)))return;message(e.message);b.disabled=false}}});$('#addon-results').querySelectorAll('[data-addon-direct]').forEach(b=>b.onclick=()=>{try{addAudio(supported[Number(b.dataset.addonDirect)].url,item.name,item.name);message('Added direct source. Browser audio support determines playback.');b.disabled=true;b.textContent='✓ Added'}catch(e){message(e.message)}})}catch{if(version===revision)message('The addon could not return streams. Try again later.')}}
function addAudio(url,filename,title){url=https(url);if(!url)throw new Error('No valid HTTPS audio link returned.');if(/\.(zip|rar|7z|mkv|mp4|avi|webm)$/i.test(filename))throw new Error('This source is an archive or video, not an audio file.');const existing=tracks.findIndex(t=>t.url===url);if(existing>=0){play(existing);return;}tracks.push({title:String(title),artist:'Cloud source · '+addon.manifest.name,url,lossless:false,format:'Cloud source · quality unverified'});render();play(tracks.length-1);toast('Starting playback in Oktawka…')}
function reconnectForPlayback(error,retry){if(error.code!=='DEBRID_AUTH_REQUIRED'||!window.monoConnectAllDebrid)return false;window.monoConnectAllDebrid(()=>{page();return retry(revision)});return true}
async function playCloudFile(file,item,version){try{const resolved=await window.monoResolveAllDebrid(file.link);if(version!==revision)return;if(resolved.delayed)throw new Error('The file is still preparing. Try this source later.');addAudio(resolved.link,resolved.filename||file.filename,file.filename.replace(/\.[^.]+$/,''));message('Starting cloud playback. Audio is also in your library.')}catch(e){if(version!==revision)return;if(reconnectForPlayback(e,v=>playCloudFile(file,item,v)))return;message(e.message)}}
async function torrentAudio(hash,item,version,id){try{message('Checking this source with AllDebrid…');const result=await window.monoAllDebridTorrent({hash,id});if(version!==revision)return;if(result.pending){$('#addon-results').innerHTML='<h3>Source is preparing</h3><p class="note">AllDebrid has added this source to your account. It is not ready yet. No background polling runs.</p><button class="primary" id="addon-check-torrent">Check availability</button>';message('Wait at least five seconds before checking again.');const nextCheck=Date.now()+5000;$('#addon-check-torrent').onclick=async()=>{if(Date.now()<nextCheck)return message('Wait a few seconds before checking again.');$('#addon-check-torrent').disabled=true;await torrentAudio(hash,item,version,result.id)};return}const files=(result.files||[]).filter(f=>!addon.builtin||!losslessOnly||/\.(flac|wav|aiff|aif)$/i.test(f.filename));$('#addon-results').innerHTML='<h3>'+escapeHTML(item.name)+'</h3>'+files.map((f,i)=>`<button class="cloud-file" data-addon-file="${i}"><span>♫</span><span><b>${escapeHTML(f.filename)}</b><small>${escapeHTML(f.path)}</small></span><span>Play in Oktawka ↗</span></button>`).join('');message(files.length?'Select an audio file to play inside Oktawka. AllDebrid resolves the link in the background.':'No supported audio files were found in this source.');$('#addon-results').querySelectorAll('[data-addon-file]').forEach(b=>b.onclick=async()=>{b.disabled=true;await playCloudFile(files[Number(b.dataset.addonFile)],item,version);if(version===revision)b.disabled=false})}catch(e){if(version===revision){if(reconnectForPlayback(e,v=>torrentAudio(hash,item,v,id)))return;message(e.message);const retry=$('#addon-check-torrent');if(retry)retry.disabled=false}}}
async function searchBuiltIn(term,version){const searchController=controller;const timeout=setTimeout(()=>searchController.abort(),25000);try{const response=await fetch('/api/cloud-search?quality='+(losslessOnly?'lossless':'all')+'&q='+encodeURIComponent(term),{signal:controller.signal,credentials:'same-origin'});let data;try{data=await response.json()}catch{throw new Error('Oktawka search returned an unreadable response. Refresh the app and retry.')}if(!response.ok)throw new Error(data.error||'Music search failed (HTTP '+response.status+').');if(version!==revision)return;if(!Array.isArray(data.releases))throw new Error('Oktawka search returned an unsupported response.');const seen=new Set();const releases=data.releases.filter(h=>{const hash=String(h.hash||'');if(!/^[a-f0-9]{40}$/i.test(hash)||seen.has(hash.toLowerCase()))return false;seen.add(hash.toLowerCase());return true});$('#addon-results').innerHTML=releases.map((h,i)=>`<button class="cloud-file" data-cloud-release="${i}"><span>♫</span><span><b>${escapeHTML(h.title||'Lossless release')}</b><small>${losslessOnly?'Listed lossless':'Audio release'} · ${Number(h.seeders)||0} seeders · quality unverified</small></span><span>Play in Oktawka ↗</span></button>`).join('')+'<p class="note">Source search by <a href="https://knaben.org/" target="_blank" rel="noopener noreferrer">Knaben</a>. Release titles and lossless labels come from the indexer. AllDebrid checks readiness after you select a release; uncached sources may need preparation.</p>';message((releases.length?`${releases.length} external releases found. Select one, then choose an audio file.`:'No releases with usable sources found. Try the artist and album title.')+(data.warning?' '+data.warning:''));$('#addon-results').querySelectorAll('[data-cloud-release]').forEach(b=>b.onclick=()=>{const h=releases[Number(b.dataset.cloudRelease)];torrentAudio(h.hash,{name:h.title||term},version)})}finally{clearTimeout(timeout)}}
let homeVersion=0,homeController=null;
async function homeMusic(browse=false){const version=++homeVersion;homeController?.abort();homeController=new AbortController();const q=browse?'':$('#home-music-query').value.trim();if(browse)$('#home-music-query').value='';const quality=$('#home-quality').value;$('#home-music-search').disabled=true;$('#browse-music').disabled=true;$('#home-music-status').textContent=q?'Searching music sources…':'Browsing music sources…';const homeSignal=homeController;const timeout=setTimeout(()=>homeSignal.abort(),25000);try{const response=await fetch('/api/cloud-search?quality='+quality+'&q='+encodeURIComponent(q),{signal:homeSignal.signal,credentials:'same-origin'});const data=await response.json();if(version!==homeVersion)return;if(!response.ok)throw new Error(data.error||'Music search is unavailable.');if(!Array.isArray(data.releases))throw new Error('Music search returned an invalid response.');$('#home-music-results').innerHTML=data.releases.map((r,i)=>`<button class="cloud-file" data-home-release="${i}"><span>♫</span><span><b>${escapeHTML(r.title)}</b><small>${quality==='lossless'?'Listed lossless':'Audio release'} · ${Number(r.seeders)||0} seeders · availability unchecked</small></span><span>Play in Oktawka ↗</span></button>`).join('');$('#home-music-status').textContent=data.releases.length?`${data.releases.length} source candidates. Select one to check audio through AllDebrid.`+(data.warning?' '+data.warning:''):'No matching releases found. Try another artist or album.'+(data.warning?' '+data.warning:'');$('#home-music-results').querySelectorAll('[data-home-release]').forEach(b=>b.onclick=()=>{const release=data.releases[Number(b.dataset.homeRelease)];losslessOnly=quality==='lossless';addon=builtIn;page();torrentAudio(release.hash,{name:release.title},revision)})}catch(e){if(version===homeVersion){const previous=!!$('#home-music-results').children?.length;$('#home-music-status').textContent=(previous?'Previous results remain below. ':'')+(e.name==='AbortError'?'Music search timed out. Use Browse music to retry.':e.message||'Could not reach music search. Retry shortly.');const retry=document.createElement('button');retry.className='source-back';retry.textContent='Retry search';retry.onclick=()=>homeMusic(browse);$('#home-music-status').append(retry)}}finally{clearTimeout(timeout);if(version===homeVersion){$('#home-music-search').disabled=false;$('#browse-music').disabled=false}}}
$('#home-music-form').onsubmit=e=>{e.preventDefault();homeMusic()};$('#browse-music').onclick=()=>homeMusic(true);$('#home-quality').onchange=()=>homeMusic(!$('#home-music-query').value.trim());
$('#dialog').addEventListener('close',()=>{revision++;controller?.abort()});
$('#music-addons').onclick=()=>page(searchTerm);window.monoOpenAddons=page;
$('#external-sources').onclick=()=>{if($('#home-main')){$('#home-main').hidden=false;$('#radio-category').hidden=true;$('#open-category').hidden=true}const panel=$('#external-sources-panel');panel.hidden=!panel.hidden;$('#external-sources').setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){panel.scrollIntoView({block:'start',behavior:'smooth'});$('#home-music-query').focus()}};

})();
